using System;
using UnityEditor;
using UnityEngine;

namespace VoxelEngine.CI
{
    [InitializeOnLoad]
    internal static class AuthoredWaterPaintBootstrap
    {
        private static Texture2D _texture;

        static AuthoredWaterPaintBootstrap()
        {
            Install();
            AssemblyReloadEvents.beforeAssemblyReload += Cleanup;
            EditorApplication.quitting += Cleanup;
        }

        private static void Install()
        {
            if (_texture != null)
                return;

            try
            {
                byte[] bytes = Convert.FromBase64String(PngBase64);
                var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false, true)
                {
                    name = "Authored Water Paint Field",
                    filterMode = FilterMode.Bilinear,
                    wrapMode = TextureWrapMode.Clamp,
                    hideFlags = HideFlags.HideAndDontSave
                };

                if (!tex.LoadImage(bytes, false))
                    throw new InvalidOperationException("Could not decode authored water paint texture.");

                tex.filterMode = FilterMode.Bilinear;
                tex.wrapMode = TextureWrapMode.Clamp;
                tex.Apply(false, true);
                _texture = tex;
                Shader.SetGlobalTexture("_AuthoredWaterTex", _texture);
                Debug.Log($"Installed authored water paint field {_texture.width}x{_texture.height}.");
            }
            catch (Exception ex)
            {
                Debug.LogError("Failed to install authored water paint field: " + ex);
            }
        }

        private static void Cleanup()
        {
            Shader.SetGlobalTexture("_AuthoredWaterTex", Texture2D.blackTexture);
            if (_texture != null)
            {
                UnityEngine.Object.DestroyImmediate(_texture);
                _texture = null;
            }
        }

        private const string PngBase64 =
            "";
    }
}
